const NAV=[['dashboard','Обзор',LayoutDashboard],['sources','Исходники',FolderOpen],['analysis','Анализ видео',ScanLine],['studio','Clip Studio',Clapperboard],['montage','Монтаж',Film],['clips','Библиотека клипов',Library],['queue','Очередь',Layers],['publishing','Публикации',Upload],['settings','Настройки',SettingsIcon]] as const;
const STAGES=['Импорт','Транскрипция','Анализ','Монтаж','Экспорт'];
const LABEL:Record<string,string>={Queued:'В очереди',Running:'Обработка',Paused:'Пауза',Completed:'Готово',Failed:'Ошибка',Cancelled:'Отменено',Imported:'Загружено',Analyzed:'Проанализировано',Transcribing:'Транскрипция',Analyzing:'Анализ',Scoring:'Оценка',Preparing:'Подготовка',Rendering:'Рендер',owned:'Собственный материал',licensed:'По лицензии',permission:'С разрешением'};
const status=(s:string)=>LABEL[s]||s;
function Badge({value}:{value:string}){return <span className={'badge '+(['Completed','Analyzed'].includes(value)?'positive':value==='Failed'?'negative':'')}>{['Completed','Analyzed'].includes(value)?<Check size={11}/>:value==='Running'?<Loader2 size={11} className="spin"/>:null}{status(value)}</span>}
function Empty({title,children,icon:Icon=Film}:{title:string;children:React.ReactNode;icon?:any}){return <div className="empty"><Icon size={30} strokeWidth={1}/><h3>{title}</h3><div>{children}</div></div>}
function Field({label,children,hint}:{label:string;children:React.ReactNode;hint?:string}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Toggle({label,checked,onChange,description}:{label:string;checked:boolean;onChange:(v:boolean)=>void;description?:string}){return <label className="toggle-row"><div><span>{label}</span>{description&&<small>{description}</small>}</div><input type="checkbox" role="switch" checked={checked} onChange={e=>onChange(e.target.checked)}/></label>}
function Modal({title,children,onClose,wide=false}:{title:string;children:React.ReactNode;onClose:()=>void;wide?:boolean}){
 const dialog=useRef<HTMLDialogElement>(null);useEffect(()=>{dialog.current?.showModal();return()=>dialog.current?.close()},[]);
 return <dialog ref={dialog} className={wide?'wide':''} onCancel={e=>{e.preventDefault();onClose()}} onClick={e=>{if(e.target===dialog.current)onClose()}}><div className="modal-title"><h2>{title}</h2><Button size="icon" variant="ghost" aria-label="Закрыть" onClick={onClose}><X size={20}/></Button></div>{children}</dialog>
}

function App(){
 const [page,setPage]=useState(location.hash.slice(1)||'dashboard'),[sources,setSources]=useState<Source[]>([]),[clips,setClips]=useState<Clip[]>([]),[jobs,setJobs]=useState<Job[]>([]),[dash,setDash]=useState<any>(null),[settings,setSettings]=useState<any>(null),[doctor,setDoctor]=useState<any>(null);
 const [sourceId,setSourceId]=useState(''),[clipId,setClipId]=useState(''),[query,setQuery]=useState(''),[importOpen,setImportOpen]=useState(false),[analyzeIds,setAnalyzeIds]=useState<string[]>([]),[notice,setNotice]=useState<{text:string;error:boolean}|null>(null),[error,setError]=useState(''),[menu,setMenu]=useState(false),[theme,setTheme]=useState(localStorage.getItem('factory-theme')||'dark');
 const [pending,setPending]=useState(false);
 const [donateOpen,setDonateOpen]=useState(false);
 const [pendingExports,setPendingExports]=useState<string[]>(()=>{try{const ids=JSON.parse(localStorage.getItem('factory-pending-exports')||'[]');return Array.isArray(ids)?ids.filter(id=>typeof id==='string'):[]}catch{return []}});
 const toast=(text:string,error=false)=>setNotice({text,error});
 const refresh=async()=>{try{const [ss,cs,js,d,s]=await Promise.all([api('/sources'),api('/clips'),api('/jobs'),api('/dashboard'),api('/settings')]);setSources(ss);setClips(cs);setJobs(js);setDash(d);setSettings(s);setError('')}catch(e){setError(String(e))}};
 const server=useServer(()=>{refresh()});
 useEffect(()=>{refresh();api('/doctor').then(setDoctor).catch(()=>{});const id=setInterval(refresh,2500);return()=>clearInterval(id)},[]);
 useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('factory-theme',theme)},[theme]);
 useEffect(()=>{if(!notice)return;const id=setTimeout(()=>setNotice(null),6500);return()=>clearTimeout(id)},[notice]);
 useEffect(()=>{const changed=()=>setPage(location.hash.slice(1)||'dashboard');window.addEventListener('hashchange',changed);return()=>window.removeEventListener('hashchange',changed)},[]);
 const go=(p:string)=>{setPage(p);location.hash=p;setMenu(false);setQuery('')};
 const openSource=(id:string)=>{setSourceId(id);go('analysis')};
 const openClip=(id:string)=>{setClipId(id);go('studio')};
 const act=async(fn:()=>Promise<any>,message?:string)=>{setPending(true);try{const r=await fn();await refresh();if(message)toast(message);return r}catch(e){toast(e instanceof Error?e.message:String(e),true);return null}finally{setPending(false)}};

 useEffect(()=>{localStorage.setItem('factory-pending-exports',JSON.stringify(pendingExports))},[pendingExports]);
 useEffect(()=>{
  const finished=new Set<string>();
  for(const id of pendingExports){
   const job=jobs.find(j=>j.id===id);
   if(job?.status==='Completed'&&job.checkpoints?.download_url){
    const link=document.createElement('a');link.href=job.checkpoints.download_url;link.download='vds-shorts-factory.zip';link.click();
    toast('Ролики готовы. ZIP отправлен на скачивание; ссылка также есть в очереди.');finished.add(id);
   }else if(job&&['Failed','Cancelled'].includes(job.status)){
    toast(job.error||'Создание ZIP отменено. Подробности — в очереди.',true);finished.add(id);
   }
  }
  if(finished.size)setPendingExports(previous=>previous.filter(id=>!finished.has(id)));
 },[jobs,pendingExports]);
 const active=jobs.filter(j=>['Running','Queued'].includes(j.status));
 return <div className="app-shell">
  <aside className={menu?'sidebar mobile-open':'sidebar'}>
   <a className="brand" href="#dashboard" onClick={()=>go('dashboard')} aria-label="VDS Shorts Factory"><img className="brand-logo on-dark" src="/brand/logo-dark.png" alt="VDS Shorts Factory" width="178" height="70"/><img className="brand-logo on-light" src="/brand/logo-light.png" alt="" width="178" height="70"/></a>
      <nav>{NAV.map(([id,label,Icon])=><button key={id} className={page===id?'nav-item active':'nav-item'} onClick={()=>go(id)}><Icon size={18} strokeWidth={1.6}/><span>{label}</span>{id==='queue'&&active.length>0&&<b>{active.length}</b>}</button>)}</nav>
   <div className="sidebar-bottom"><DonateButton onClick={()=>{setDonateOpen(true);setMenu(false)}}/><div className="storage-label" title="Место на диске, где программа хранит видео и проекты"><HardDrive size={14}/><span>Диск: свободно {dash?`${bytes(dash.disk.free)} из ${bytes(dash.disk.total)}`:'…'}</span></div><div className={'disk-track'+(dash&&dash.disk.free<5*1024**3?' low':'')}><i style={{width:dash?`${Math.min(100,(1-dash.disk.free/dash.disk.total)*100)}%`:'0%'}}/></div><button className="theme-control" onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={15}/>:<Moon size={15}/>} {theme==='dark'?'Светлая тема':'Тёмная тема'}</button></div>
  </aside>
  <div className="app-main"><header className="topbar"><div className="crumb"><Button size="icon" className="mobile-menu" variant="ghost" aria-label="Меню" onClick={()=>setMenu(!menu)}><Menu size={19}/></Button></div><div className="top-search"><Search size={15}/><input aria-label="Поиск видео и клипов" placeholder="Поиск в студии…" value={query} onChange={e=>setQuery(e.target.value)}/></div><ServerBadge server={server} activeJobs={jobs.filter(j=>j.status==='Running').length}/></header>
  <main>
   <ServerDownBanner server={server}/>{server.state==='online'&&error&&<div className="error-banner"><AlertCircle size={16}/><span>{error}</span><Button size="sm" onClick={refresh}>Повторить</Button></div>}
   {!dash?<div className="loading-frame"><div className="skeleton title"/><div className="skeleton block"/><div className="skeleton block"/></div>:<>
   {page==='dashboard'&&<><PageTitle title="Студия в работе" subtitle="Из длинного видео — в моменты, которые хочется досмотреть." action={<Button variant="default" onClick={()=>setImportOpen(true)}><Plus size={16}/>Добавить видео</Button>}/>
    <div className="overview-grid"><div className="overview-main"><div className="kpis">{[['Исходники',dash.sources,'В локальной библиотеке'],['Найдено моментов',dash.clips,'AI + локальный анализ'],['Готовые клипы',dash.rendered,'Проверенные MP4']].map(([label,n,caption])=><div key={label}><span>{label}</span><strong>{n}</strong><small>{caption}</small></div>)}</div>
     <div className="import-stage" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();setImportOpen(true);(window as any).__droppedFiles=Array.from(e.dataTransfer.files)}}><div className="stage-top"><span>От исходника к готовому ролику</span><span className="micro">01 — 05</span></div><div className="film-device" aria-hidden="true"><div className="film-wide"><Film size={30} strokeWidth={1}/><span>Длинное видео</span><i/></div><div className="film-route"><span/><Scissors size={18}/><span/></div><div className="film-tall"><Subtitles size={25} strokeWidth={1}/><i/><i/><b>9:16</b></div></div><h2>{sources.length?'Следующая история начинается здесь':'Найдите сильный момент'}</h2><p>Вставьте ссылку YouTube. Найдите фрагменты.<br/>Выберите момент и создайте ролик с субтитрами.</p><Button variant="default" onClick={()=>setImportOpen(true)}><Upload size={16}/>Импортировать видео<ArrowRight size={15}/></Button><small>YouTube · MP4, MOV, MKV, WebM</small></div>
     <div className="pipeline-strip">{STAGES.map((s,i)=><React.Fragment key={s}><div><span>{String(i+1).padStart(2,'0')}</span>{s}</div>{i<4&&<ChevronRight size={13}/>}</React.Fragment>)}</div>
    </div><div className="overview-rail"><div className="section-head"><h2>Очередь обработки</h2><button onClick={()=>go('queue')}><ArrowUpRight size={17}/></button></div><div className="panel queue-mini">{active.length?active.slice(0,3).map(j=><div className="mini-job" key={j.id}><strong>{j.clip_title||j.source_name}</strong><span>{status(j.stage)}</span><div className="progress"><i style={{width:j.progress+'%'}}/></div></div>):<><div className="quiet-icon"><Layers size={23} strokeWidth={1}/></div><h3>Очередь свободна</h3><p>Добавьте видео и запустите анализ. Задачи сохраняются после перезапуска.</p><Button size="sm" onClick={()=>go('sources')}>К исходникам<ArrowRight size={14}/></Button></>}</div>
      <div className="section-head"><h2>Движок студии</h2><button onClick={()=>go('settings')} aria-label="Настроить движок"><SlidersHorizontal size={16}/></button></div><div className="panel engine-panel"><div><span>Транскрипция</span><strong>Whisper · локально</strong></div><div><span>Анализ моментов</span><strong>{settings?.values.provider==='openai'?'OpenAI':settings?.values.provider==='gemini'?'Gemini':'Локальная эвристика'}</strong></div><div><span>Экспорт</span><strong>FFmpeg · H.264</strong></div><div><span>Субтитры</span><strong>Word-level · RU / EN</strong></div><p>{(settings?.values.provider==='openai'?settings?.openai_key_connected:settings?.key_connected)?'API-ключ сохранён. Облачный запуск требует согласия.':'AI-провайдер не подключён. Локальная обработка доступна без API.'}</p><button className="text-link" onClick={()=>go('settings')}>Настроить AI<ArrowUpRight size={14}/></button></div>
    </div></div><div className="section-head recent-head"><h2>Последние исходники <span>{sources.length}</span></h2><button onClick={()=>go('sources')}>Все исходники<ArrowRight size={14}/></button></div>{sources.length?<SourceRows sources={sources.slice(0,3)} onOpen={openSource} onAnalyze={(id:string)=>setAnalyzeIds([id])}/>:<div className="empty-row">Исходников пока нет. Ваши файлы появятся здесь после импорта.</div>}
   </>}
   {page==='sources'&&<SourcesPage sources={sources.filter(s=>s.name.toLowerCase().includes(query.toLowerCase()))} onImport={()=>setImportOpen(true)} onOpen={openSource} onAnalyze={setAnalyzeIds} act={act}/>}
   {page==='analysis'&&<AnalysisPage sourceId={sourceId||sources[0]?.id} sources={sources} onSelect={setSourceId} onAnalyze={(id:string)=>setAnalyzeIds([id])} onClip={openClip} act={act} onImport={()=>setImportOpen(true)} jobs={jobs}/>}
   {page==='studio'&&<Studio clipId={clipId||clips.find(c=>c.media_url)?.id||clips[0]?.id} clips={clips} onSelect={setClipId} act={act} toast={toast} onSources={()=>go('sources')} presets={settings?.presets||{}} jobs={jobs}/>}
   {page==='clips'&&<ClipLibrary clips={clips.filter(c=>c.title.toLowerCase().includes(query.toLowerCase()))} sources={sources} onOpen={openClip} act={act} config={settings} onBatchStarted={(id:string)=>setPendingExports(previous=>[...new Set([...previous,id])])}/>}
   {page==='montage'&&<MontagePage clips={clips} sources={sources} jobs={jobs} toast={toast} onQueue={()=>go('queue')}/>}
   {page==='queue'&&<QueuePage jobs={jobs} act={act} pending={pending}/>}
   {page==='publishing'&&<PublishingPage act={act}/>}
   {page==='settings'&&settings&&<SettingsPage config={settings} doctor={doctor} dash={dash} act={act} toast={toast}/>}
   </>}
  </main><footer className="app-footer"><span>VDS Shorts Factory</span><span>Локальная студия · 127.0.0.1</span><span>{active.length?`${active.length} задач в обработке`:'Всё сохранено локально'}</span></footer></div>
  {importOpen&&<ImportDialog onClose={()=>setImportOpen(false)} act={act} toast={toast} config={settings} onQueue={()=>go('queue')}/>}
  {analyzeIds.length>0&&settings&&<AnalyzeDialog ids={analyzeIds} config={settings} onClose={()=>setAnalyzeIds([])} act={act} onQueue={()=>go('queue')}/>}
  {donateOpen&&<DonateDialog onClose={()=>setDonateOpen(false)}/>}
  {notice&&<div role="status" className={'toast '+(notice.error?'error':'')}>{notice.error?<AlertCircle size={18}/>:<CheckCircle2 size={18}/>}<span>{notice.text}</span><button aria-label="Закрыть уведомление" onClick={()=>setNotice(null)}><X size={16}/></button></div>}
 </div>
}

function PageTitle({title,subtitle,action}:{title:string;subtitle?:string;action?:React.ReactNode}){return <div className="page-title"><div><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>}
function SourceRows({sources,onOpen,onAnalyze}:{sources:Source[];onOpen:(id:string)=>void;onAnalyze:(id:string)=>void}){return <div className="source-rows">{sources.map(s=><div className="source-row" key={s.id}><button className="source-identity" onClick={()=>onOpen(s.id)}>{s.thumbnail_url?<img src={s.thumbnail_url} alt=""/>:<div className="thumbnail-fallback"><Film size={20}/></div>}<div><strong>{s.name}</strong><small>{s.kind==='youtube'?'YouTube · для рендера нужен файл':`${s.width} × ${s.height} · ${bytes(s.size)}`}</small></div></button><div className="source-duration">{time(s.duration)}<small>{s.clip_count} кандидатов</small></div><Badge value={s.status}/><Button size="sm" onClick={()=>onAnalyze(s.id)}><ScanLine size={14}/>Анализ</Button></div>)}</div>}

function SourcesPage({sources,onImport,onOpen,onAnalyze,act}:any){const [selected,setSelected]=useState<string[]>([]),[filter,setFilter]=useState('all');const filtered=sources.filter((s:Source)=>filter==='all'||s.kind===filter);return <><PageTitle title="Исходники" subtitle={`${sources.length} видео · оригиналы хранятся на этом компьютере`} action={<Button variant="default" onClick={onImport}><Plus size={16}/>Добавить видео</Button>}/><div className="toolbar"><div className="tabs">{[['all','Все видео'],['local','Локальные'],['youtube','YouTube']].map(([id,label])=><button className={filter===id?'selected':''} onClick={()=>setFilter(id)} key={id}>{label}</button>)}</div>{selected.length>0&&<Button size="sm" onClick={()=>onAnalyze(selected)}><ScanLine size={14}/>Анализировать {selected.length}</Button>}</div>{filtered.length?<div className="source-grid">{filtered.map((s:Source)=><article className="source-card" key={s.id}><div className="source-cover"><button className="cover-open" onClick={()=>onOpen(s.id)} aria-label={`Открыть ${s.name}`}>{s.thumbnail_url?<img src={s.thumbnail_url} alt={s.name}/>:<Film size={40} strokeWidth={1}/>}<span className="cover-play"><Play size={18} fill="currentColor"/></span></button><label className="cover-check"><input aria-label={`Выбрать ${s.name}`} type="checkbox" checked={selected.includes(s.id)} onChange={e=>setSelected(e.target.checked?[...selected,s.id]:selected.filter(id=>id!==s.id))}/></label><span className="cover-time">{time(s.duration)}</span></div><div className="source-card-content"><div className="spread"><Badge value={s.status}/><small>{s.kind==='local'?bytes(s.size):'YouTube URL'}</small></div><button className="card-title" onClick={()=>onOpen(s.id)}>{s.name}</button><p><ShieldCheck size={12}/>{status(s.rights?.status)} · {s.clip_count} моментов</p><div className="card-actions"><Button size="sm" onClick={()=>onAnalyze([s.id])}><ScanLine size={14}/>Анализировать</Button><Button size="icon" variant="ghost" aria-label="Архивировать видео" onClick={()=>{if(confirm(`Убрать «${s.name}» из библиотеки? Оригинал сохранится на диске.`))act(()=>api('/sources/'+s.id,{method:'DELETE'}),'Видео архивировано')}}><Trash2 size={15}/></Button></div></div></article>)}</div>:<Empty title="Добавьте первый исходник" icon={FolderOpen}><p>Видео, интервью, подкаст или лекция — начните с вашего материала.</p><Button variant="default" onClick={onImport}><Upload size={16}/>Импортировать видео</Button></Empty>}</>}

function ImportDialog({onClose,act,toast,config,onQueue}:any){
 const [mode,setMode]=useState((window as any).__droppedFiles?.length?'files':'url'),[files,setFiles]=useState<File[]>((window as any).__droppedFiles||[]),[path,setPath]=useState(''),[url,setUrl]=useState(''),[download,setDownload]=useState(true),[rights,setRights]=useState('owned'),[license,setLicense]=useState('Собственный материал'),[confirmed,setConfirmed]=useState(false),[busy,setBusy]=useState(false),[results,setResults]=useState<any[]>([]);const input=useRef<HTMLInputElement>(null);
 useEffect(()=>{delete (window as any).__droppedFiles},[]);
 const [useAccount,setUseAccount]=useState(false),[sessionConnected,setSessionConnected]=useState(false),[analyzeAfter,setAnalyzeAfter]=useState(true),[cloudConsent,setCloudConsent]=useState(false);
 const [importError,setImportError]=useState('');
 const selectMode=(next:string)=>{setMode(next);setImportError('');setResults([])};
 const submit=async()=>{
  setBusy(true);setImportError('');setResults([]);
  try{
   const result=await act(async()=>{
    try{
     if(mode==='files'){
      const form=new FormData();files.forEach(f=>form.append('files',f));
      form.append('rights_status',rights);form.append('license',license);
      return await api('/import/files',{method:'POST',body:form});
     }
     if(mode==='folder')return await post('/import/folder',{path,rights_status:rights,license});
     if(download){
      const v=config?.values||{};
      const options={min_duration:v.min_duration??20,max_duration:v.max_duration??40,target_count:v.target_count??5,
       score_threshold:v.score_threshold??35,language:v.language??'auto',profile:v.profile??'Educational',cloud_consent:cloudConsent};
      return [await post('/import/youtube',{url,rights_status:rights,license,use_account:useAccount,analyze_after:analyzeAfter,options})];
     }
     return [await post('/import/url',{url,rights_status:rights,license,download:false,use_account:useAccount})];
    }catch(e){setImportError(e instanceof Error?e.message:String(e));return null}
   });
   if(result){
    if(result[0]?.queued){toast(result[0].already_downloaded?'Исходник уже скачан → анализ в очереди':'Скачивание поставлено в очередь'+(analyzeAfter?' → затем анализ':''));onClose();onQueue?.();return}
    setResults(result);
    if(result.every((r:any)=>!r.error)){
     toast(`Добавлено: ${result.filter((r:any)=>!r.duplicate).length}; дубликатов: ${result.filter((r:any)=>r.duplicate).length}`);
     onClose();
    }
   }
  }finally{setBusy(false)}
 };
 return <Modal title="Импорт видео" onClose={()=>!busy&&onClose()}><div className="modal-body"><div className="tabs import-tabs">{[['url','YouTube',Link],['files','Файлы',Upload],['folder','Папка',FolderInput]].map(([id,label,Icon]:any)=><button className={mode===id?'selected':''} key={id} disabled={busy} onClick={()=>selectMode(id)}><Icon size={15}/>{label}</button>)}</div>{mode==='files'?<><div className="dropzone" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();setFiles(Array.from(e.dataTransfer.files))}}><Upload size={28} strokeWidth={1}/><h3>{files.length?`${files.length} файлов выбрано`:'Перетащите ваши видео'}</h3><p>MP4, MOV, MKV, WebM · до 100 файлов</p><Button onClick={()=>input.current?.click()}>Выбрать файлы</Button><input ref={input} type="file" multiple accept=".mp4,.mov,.mkv,.webm" hidden onChange={e=>setFiles(Array.from(e.target.files||[]))}/></div>{files.length>0&&<div className="file-list">{files.slice(0,8).map((f,i)=><div key={i}><Film size={14}/><span>{f.name}</span><small>{bytes(f.size)}</small></div>)}</div>}</>:mode==='folder'?<Field label="Путь к папке" hint="Импортируются видео из выбранной папки без вложенных каталогов. Файлы копируются в студию."><input placeholder="/Users/you/Movies/Interview" value={path} onChange={e=>setPath(e.target.value)}/></Field>:<><YouTubeAccount onChange={session=>{setSessionConnected(session.connected);setUseAccount(session.connected)}}/><Field label="Ссылка на видео YouTube"><input type="url" placeholder="https://www.youtube.com/watch?v=…" value={url} onChange={e=>setUrl(e.target.value)}/></Field><Toggle label="Скачать исходник через yt-dlp" checked={download} onChange={setDownload} description="Только при наличии разрешения. Без скачивания доступен лишь облачный URL-анализ; монтаж требует файла."/><Toggle label="Использовать мой аккаунт" checked={useAccount} onChange={setUseAccount} description={sessionConnected?'Используется подключённая локальная сессия YouTube.':'Для публичных видео можно без аккаунта. Для входа подключите сессию выше.'}/>{download&&<><Toggle label="После скачивания найти моменты" checked={analyzeAfter} onChange={setAnalyzeAfter} description="Исходник сохранится в библиотеке. Затем запустятся транскрипция и анализ по настройкам студии."/>{analyzeAfter&&['gemini','openai'].includes(config?.values.provider)&&config?.values.cloud_enabled&&<label className="check-row"><input type="checkbox" checked={cloudConsent} onChange={e=>setCloudConsent(e.target.checked)}/>Разрешаю отправить транскрипцию и кадры/превью в {config?.values.provider==='openai'?'OpenAI':'Gemini'}. Без этого анализ выполняется локально.</label>}</>}<div className="notice-box">Скачивание до 1080p с прогрессом, паузой и отменой в очереди. Вход даёт доступ только к видео, которые доступны вашему аккаунту.</div></>}
 <div aria-live="polite">{importError&&<div className="notice-box import-error" role="alert"><p>{importError}</p>{mode==='url'&&<div className="button-row"><Button onClick={()=>selectMode('files')}><Upload size={15}/>Загрузить локальный файл</Button></div>}</div>}</div>
 <div className="form-grid"><Field label="Права на материал"><select value={rights} onChange={e=>setRights(e.target.value)}><option value="owned">Собственный материал</option><option value="licensed">По лицензии</option><option value="permission">Есть разрешение</option></select></Field><Field label="Лицензия / основание"><input value={license} onChange={e=>setLicense(e.target.value)} maxLength={500}/></Field></div><label className="check-row"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>Подтверждаю право на обработку этого материала</label>{results.filter(r=>r.error).map((r,i)=><p className="inline-error" key={i}>{r.filename}: {r.error}</p>)}<div className="modal-actions"><Button onClick={onClose} disabled={busy}>Отмена</Button><Button variant="default" disabled={busy||!confirmed||!license.trim()||(mode==='files'?!files.length:mode==='folder'?!path:!url)||(mode==='url'&&useAccount&&!sessionConnected)} onClick={submit}>{busy?<Loader2 size={15} className="spin"/>:<Upload size={15}/>} {busy?'Импортирую…':mode==='url'&&download?'Скачать и '+(analyzeAfter?'анализировать':'сохранить'):'Импортировать'}</Button></div></div></Modal>
}

function AnalyzeDialog({ids,config,onClose,act,onQueue}:any){const [values,setValues]=useState<any>({...config.values}),[consent,setConsent]=useState(false),[busy,setBusy]=useState(false);const change=(k:string,v:any)=>setValues({...values,[k]:v});return <Modal title={`Анализировать видео · ${ids.length}`} onClose={onClose}><div className="modal-body"><p className="muted">Речь → смысловые фрагменты → кандидаты. Количество — верхняя граница, а не обязательный план.</p><div className="form-grid"><Field label="Количество клипов"><select value={values.target_count} onChange={e=>change('target_count',+e.target.value)}>{[0,3,5,10,20,50,100].map(n=><option key={n} value={n}>{n||'Auto'}</option>)}</select></Field><Field label="Профиль контента"><select value={values.profile} onChange={e=>change('profile',e.target.value)}>{['Podcast','Interviews','Tech Reviews','Educational','Entertainment','Real Estate','Business'].map(p=><option key={p}>{p}</option>)}</select></Field><Field label="Минимум, секунд"><input type="number" min={3} max={180} value={values.min_duration} onChange={e=>change('min_duration',+e.target.value)}/></Field><Field label="Максимум, секунд"><input type="number" min={3} max={180} value={values.max_duration} onChange={e=>change('max_duration',+e.target.value)}/></Field><Field label="Порог оценки"><input type="number" min={0} max={100} value={values.score_threshold} onChange={e=>change('score_threshold',+e.target.value)}/></Field><Field label="Язык"><select value={values.language} onChange={e=>change('language',e.target.value)}><option value="auto">Автоматически</option><option value="ru">Русский</option><option value="en">English</option></select></Field></div>{['gemini','openai'].includes(config.values.provider)&&config.values.cloud_enabled?<label className="cloud-consent"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/><span>Разрешаю отправить транскрипцию и кадры/превью выбранных фрагментов в {config.values.provider==='openai'?'OpenAI':'Gemini'} для этого анализа. Без согласия запускается локальная эвристика.</span></label>:<div className="notice-box"><Cpu size={17}/><span>Локальный режим: Whisper, сцены и базовое ранжирование. Содержимое видео не отправляется в облако. При первом запуске загрузятся веса Whisper.</span></div>}<div className="modal-actions"><Button onClick={onClose}>Отмена</Button><Button variant="default" disabled={busy||values.max_duration<values.min_duration} onClick={async()=>{setBusy(true);const result=await act(()=>Promise.all(ids.map((id:string)=>post(`/sources/${id}/analyze`,{cloud_consent:consent,...Object.fromEntries(['min_duration','max_duration','target_count','score_threshold','language','profile'].map(k=>[k,values[k]]))}))),`В очередь добавлено: ${ids.length}`);setBusy(false);if(result){onClose();onQueue()}}}><ScanLine size={16}/>{busy?'Добавляю…':consent?`Запустить ${config.values.provider==='openai'?'OpenAI':'Gemini'}-анализ`:'Запустить локальный анализ'}</Button></div></div></Modal>}

function AnalysisPage({sourceId,sources,onSelect,onAnalyze,onClip,act,onImport,jobs}:any){const [detail,setDetail]=useState<Source|null>(null),[err,setErr]=useState(''),[start,setStart]=useState(0),[end,setEnd]=useState(20),[tab,setTab]=useState('transcript');const player=useRef<HTMLVideoElement>(null);const [position,setPosition]=useState(0);useEffect(()=>{if(!sourceId)return;let alive=true;setDetail(null);const load=()=>api('/sources/'+sourceId).then(d=>{if(alive){setDetail(d);setErr('')}}).catch(e=>{if(alive)setErr(e.message)});load();const id=setInterval(load,3000);return()=>{alive=false;clearInterval(id)}},[sourceId]);if(!sourceId)return <><PageTitle title="Анализ видео"/><Empty title="Выберите исходное видео" icon={ScanLine}><p>Загрузите материал для анализа речи и поиска фрагментов.</p><Button onClick={onImport}>Добавить видео</Button></Empty></>;const current=jobs.find((j:Job)=>j.source_id===sourceId&&j.kind==='analysis'&&['Queued','Running','Paused'].includes(j.status));return <><PageTitle title="Анализ видео" subtitle={detail?.name||'Загружаю исходник…'} action={<Button variant="default" disabled={!!current} onClick={()=>onAnalyze(sourceId)}><ScanLine size={16}/>{current?status(current.stage):'Анализировать'}</Button>}/><div className="toolbar"><select aria-label="Исходное видео" value={sourceId} onChange={e=>onSelect(e.target.value)}>{sources.map((s:Source)=><option key={s.id} value={s.id}>{s.name}</option>)}</select>{detail&&<span className="muted">{time(detail.duration)} · {detail.scenes?.length||0} сцен · {status(detail.rights?.status)}</span>}</div>{err&&<div className="notice-box">{err}</div>}{detail?<div className="analysis-layout"><div className="analysis-main">{detail.media_url?<video ref={player} className="source-player" src={detail.media_url} controls preload="metadata" onTimeUpdate={e=>setPosition(e.currentTarget.currentTime)}/>:<div className="url-preview"><Link size={32}/><p>Публичный URL · локального исходника нет</p><a href={detail.url} target="_blank" rel="noreferrer">Открыть на YouTube<ExternalLink size={14}/></a></div>}<div className="source-timeline" title="Нажмите, чтобы перейти к позиции видео" onClick={e=>{if(player.current)player.current.currentTime=(e.clientX-e.currentTarget.getBoundingClientRect().left)/e.currentTarget.clientWidth*detail.duration}}><div className="scene-marks">{detail.scenes?.map((s:any,i:number)=><i key={i} style={{left:(s.start/detail.duration*100)+'%'}}/>)}</div>{detail.clips?.map(c=><span key={c.id} style={{left:c.start/detail.duration*100+'%',width:(c.end-c.start)/detail.duration*100+'%'}}/>)}<b style={{left:position/detail.duration*100+'%'}}/></div><div className="timeline-labels"><span>00:00</span><span>{time(position)}</span><span>{time(detail.duration)}</span></div><div className="tabs"><button className={tab==='transcript'?'selected':''} onClick={()=>setTab('transcript')}>Транскрипция</button><button className={tab==='manual'?'selected':''} onClick={()=>setTab('manual')}>Ручной фрагмент</button><button className={tab==='rights'?'selected':''} onClick={()=>setTab('rights')}>Источник и права</button></div>{tab==='transcript'?<div className="transcript">{detail.transcript?.segments?.length?detail.transcript.segments.map((s:any,i:number)=><button className={position>=s.start&&position<s.end?'transcript-row speaking':'transcript-row'} key={i} onClick={()=>{if(player.current)player.current.currentTime=s.start}}><time>{time(s.start)}</time><span>{s.text}</span></button>):<div className="empty-inline">Транскрипция появится после анализа. MLX выполняется локально.</div>}</div>:tab==='manual'?<div className="panel manual-panel"><p>Создайте собственный фрагмент по таймкодам, затем откройте редактор.</p><div className="form-grid"><Field label="Начало, с"><input type="number" min={0} max={detail.duration} step="0.1" value={start} onChange={e=>setStart(+e.target.value)}/></Field><Field label="Конец, с"><input type="number" min={0} max={detail.duration} step="0.1" value={end} onChange={e=>setEnd(+e.target.value)}/></Field></div><Button disabled={end<=start||end>detail.duration} onClick={async()=>{const c=await act(()=>post(`/sources/${sourceId}/manual-clip`,{start,end}));if(c)onClip(c.id)}}><Scissors size={14}/>Создать фрагмент</Button></div>:<div className="panel rights-panel"><p>Статус: {status(detail.rights.status)}</p><p>Основание: {detail.rights.license}</p><p>Источник: {detail.rights.origin}</p></div>}</div><div className="candidates"><div className="section-head"><h2>Лучшие моменты</h2><span>{detail.clips?.length||0}</span></div><p className="muted small-text">Оценка — ориентир редактора, не прогноз просмотров. Проверьте контекст и цитаты.</p>{detail.clips?.length?detail.clips.map(c=><article className="candidate panel" key={c.id}><div className="spread"><span className="score">{Math.round(c.score)}<small>/100</small></span><span className="provider">{c.provider==='gemini'?'Gemini · 2 прохода':c.provider==='manual'?'Ручной выбор':'Локальная эвристика'}</span></div><h3>{c.title}</h3><button className="candidate-time" onClick={()=>{if(player.current)player.current.currentTime=c.start}}><Play size={12}/>{time(c.start)} — {time(c.end)}<span>{Math.round(c.end-c.start)} с</span></button><p>{c.data.reason}</p>{c.data.scores&&<details><summary>Оценки и предупреждения</summary><div className="score-details">{Object.entries(c.data.scores).map(([k,v]:any)=><div key={k}><span>{k.replaceAll('_',' ')}</span><strong>{Math.round(v)}</strong></div>)}</div>{c.data.warnings?.map((w:string,i:number)=><p className="small-text" key={i}>{w}</p>)}</details>}<div className="card-actions"><label className="check-row"><input type="checkbox" checked={!!c.approved} onChange={e=>act(()=>api('/clips/'+c.id,{method:'PATCH',body:JSON.stringify({approved:e.target.checked})}))}/>В отобранные</label><Button size="sm" onClick={()=>onClip(c.id)}>В редактор<ArrowUpRight size={14}/></Button></div></article>):<div className="empty-inline">{current?'Анализ выполняется. Кандидаты появятся после завершения.':'Запустите анализ или создайте ручной фрагмент.'}</div>}</div></div>:<div className="skeleton block"/>}</>}

function Studio({clipId,clips,onSelect,act,toast,onSources,presets,jobs}:any){
 const [clip,setClip]=useState<Clip|null>(null),[plan,setPlan]=useState<any>(null),[dirty,setDirty]=useState(false),[tab,setTab]=useState('trim'),[preview,setPreview]=useState(false),[position,setPosition]=useState(0),[saving,setSaving]=useState(false),[title,setTitle]=useState('');const player=useRef<HTMLVideoElement>(null);
 const load=async()=>{if(!clipId)return;const c=await api('/clips/'+clipId);setClip(c);setPlan(c.plan);setTitle(c.title);setDirty(false);setPreview(!!c.media_url)};
 useEffect(()=>{setClip(null);setPlan(null);load().catch((e:any)=>toast(e.message,true))},[clipId]);
 const current=jobs.find((j:Job)=>j.clip_id===clipId&&['Queued','Running','Paused'].includes(j.status));const lastStatus=useRef('');useEffect(()=>{const j=jobs.find((j:Job)=>j.clip_id===clipId);if(j?.status==='Completed'&&lastStatus.current!==j.id){lastStatus.current=j.id;if(!dirty)load().catch(()=>{})}},[jobs]);
 const patch=(k:string,v:any)=>{setPlan((p:any)=>({...p,[k]:v}));setDirty(true);setPreview(false)};
 const sub=(k:string,v:any)=>{setPlan((p:any)=>({...p,subtitles:{...p.subtitles,[k]:v}}));setDirty(true);setPreview(false)};
 const save=async()=>{setSaving(true);const c=await act(async()=>{await api('/clips/'+clipId,{method:'PATCH',body:JSON.stringify({title})});return api('/clips/'+clipId+'/plan',{method:'PUT',body:JSON.stringify(plan)})},'Монтаж сохранён');setSaving(false);if(c){setClip({...clip,...c});setDirty(false)}return c};
 if(!clipId)return <><PageTitle title="Clip Studio"/><Empty title="Пока нечего монтировать" icon={Clapperboard}><p>Выберите момент в анализе видео или создайте фрагмент вручную.</p><Button onClick={onSources}>Открыть исходники</Button></Empty></>;
 if(!clip||!plan)return <><PageTitle title="Clip Studio"/><div className="skeleton block"/></>;
 const words=(clip.transcript?.segments||[]).flatMap((s:any)=>s.words||[]);const activeSegment=plan.segments[0];const sourcePos=position;const phrase=words.filter((w:any)=>w.end>=sourcePos-1&&w.start<=sourcePos+1).slice(0,plan.subtitles.words_per_line);const duration=plan.segments.reduce((sum:number,s:any)=>sum+s.end-s.start,0);
 const changeSegment=(i:number,k:string,v:number)=>patch('segments',plan.segments.map((s:any,n:number)=>n===i?{...s,[k]:v}:s));
 const playSource=()=>{if(player.current){player.current.currentTime=activeSegment.start;player.current.play().catch(()=>{})}};
 return <><PageTitle title="Clip Studio" subtitle={`${clip.source?.name} · ревизия ${clip.revision}${dirty?' · есть несохранённые изменения':''}`} action={<div className="button-row"><Button disabled={saving||!dirty} onClick={save}>Сохранить</Button><Button variant="default" disabled={!!current||saving} onClick={async()=>{if(dirty&&!(await save()))return;await act(()=>post(`/clips/${clipId}/render`),'Рендер добавлен в очередь')}}>{current?<Loader2 className="spin" size={15}/>:<Clapperboard size={15}/>} {current?status(current.stage):'Generate Reel'}</Button></div>}/><div className="toolbar"><select aria-label="Редактируемый клип" value={clipId} onChange={e=>{if(!dirty||confirm('Перейти к другому клипу без сохранения?'))onSelect(e.target.value)}}>{clips.map((c:Clip)=><option key={c.id} value={c.id}>{c.title}</option>)}</select><span className="muted">{duration.toFixed(1)} с · {plan.aspect} · {plan.fps} fps</span></div><div className="studio-grid"><div className="preview-panel"><div className="preview-heading"><span>{preview?'Готовый MP4':'Предпросмотр исходника'}</span>{clip.media_url&&<button onClick={()=>setPreview(!preview)}>{preview?'Показать исходник':'Показать MP4'}<ArrowRight size={13}/></button>}</div><div className={'portrait-player '+(!preview&&plan.crop_mode==='blur'?'fit-video':'')} style={{aspectRatio:plan.aspect.replace(':','/')}}><video ref={player} key={`${clipId}-${preview}`} src={preview?clip.media_url!:clip.source?.media_url||undefined} controls preload="metadata" style={!preview?{objectPosition:`${plan.crop_x*100}% ${plan.crop_y*100}%`}:undefined} onLoadedMetadata={e=>{if(!preview)e.currentTarget.currentTime=activeSegment.start}} onTimeUpdate={e=>{setPosition(e.currentTarget.currentTime);if(!preview&&e.currentTarget.currentTime>activeSegment.end&&!e.currentTarget.paused)e.currentTarget.pause()}}/>{!preview&&plan.subtitles.enabled&&phrase.length>0&&<div className="live-captions" style={{top:plan.subtitles.position*100+'%',fontSize:Math.min(32,plan.subtitles.size/1080*300),fontWeight:plan.subtitles.bold?600:400,color:plan.subtitles.color,fontFamily:plan.subtitles.font}}>{phrase.map((w:any,i:number)=><span key={i} style={{color:plan.subtitles.animation!=='none'&&w.start<=position&&w.end>=position?plan.subtitles.active_color:plan.subtitles.color}}>{w.word} </span>)}</div>}</div><p className="preview-note">{preview?`Реальный файл · ${clip.qc?.passed?'автопроверка пройдена':'QC не найден'}${clip.stale?' · устаревшая ревизия, нужен рендер':''}`:'Приблизительный preview. Кроп и стили проверяются на готовом MP4.'}</p><div className="preview-downloads">{clip.media_url&&<><a className="button secondary small" href={clip.media_url+'?download=true'} download><Download size={14}/>MP4</a><a className="button ghost small" href={clip.media_url+'?download=true&format=srt'} download>SRT</a><a className="button ghost small" href={clip.media_url+'?download=true&format=ass'} download>ASS</a></>}</div>{clip.qc&&<details className="qc-details"><summary><CheckCircle2 size={14}/>Отчёт проверки</summary><p>{clip.qc.width}×{clip.qc.height} · {clip.qc.fps}fps · {clip.qc.duration.toFixed(2)}s · {bytes(clip.qc.size)}</p><p>Декодирование: {clip.qc.full_decode?'все кадры':'—'} · {clip.qc.encoder}</p>{clip.qc.warnings?.map((w:string,i:number)=><p key={i}>{w}</p>)}<p>Смысл, точность текста и кадрирование требуют ручного просмотра.</p></details>}</div>
 <div className="edit-panel"><div className="editor-tabs">{[['trim','Монтаж',Scissors],['crop','Кадр',ScanLine],['subtitles','Субтитры',Subtitles],['audio','Аудио',AudioLines],['metadata','Тексты',SlidersHorizontal]].map(([id,label,Icon]:any)=><button key={id} className={tab===id?'selected':''} onClick={()=>setTab(id)}><Icon size={16}/>{label}</button>)}</div><div className="edit-content">{tab==='trim'?<><h2>Границы и склейка</h2><p className="muted">Таймкоды в секундах исходного видео. Сегменты склеиваются в указанном порядке.</p>{plan.segments.map((segment:any,i:number)=><div className="segment-editor" key={i}><div className="spread"><strong>Сегмент {i+1}</strong>{plan.segments.length>1&&<Button size="icon" variant="ghost" aria-label="Удалить сегмент" onClick={()=>patch('segments',plan.segments.filter((_:any,n:number)=>n!==i))}><X size={15}/></Button>}</div><div className="form-grid"><Field label="Начало, с"><input type="number" step="0.01" min={0} max={segment.end-.01} value={segment.start} onChange={e=>changeSegment(i,'start',+e.target.value)}/></Field><Field label="Конец, с"><input type="number" step="0.01" min={segment.start+.01} max={clip.source?.duration} value={segment.end} onChange={e=>changeSegment(i,'end',+e.target.value)}/></Field></div><label className="range-label">Начало<input aria-label={`Начало сегмента ${i+1}`} type="range" min={0} max={clip.source?.duration} step="0.05" value={segment.start} onChange={e=>{const v=Math.min(+e.target.value,segment.end-.1);changeSegment(i,'start',v);if(player.current&&!preview)player.current.currentTime=v}}/></label><label className="range-label">Конец<input aria-label={`Конец сегмента ${i+1}`} type="range" min={0} max={clip.source?.duration} step="0.05" value={segment.end} onChange={e=>changeSegment(i,'end',Math.max(+e.target.value,segment.start+.1))}/></label></div>)}<div className="button-row"><Button size="sm" onClick={()=>patch('segments',[...plan.segments,{start:activeSegment.start,end:activeSegment.end}])}><Plus size={14}/>Добавить сегмент</Button><Button size="sm" onClick={playSource}><Play size={13}/>Прослушать границы</Button></div><Toggle label="Сократить паузы длиннее 1,1 с" description="Паузы определяются по word timestamps; остаётся небольшой воздух между фразами." checked={plan.remove_pauses} onChange={v=>patch('remove_pauses',v)}/><div className="form-grid"><Field label="Формат"><select value={plan.aspect} onChange={e=>patch('aspect',e.target.value)}>{['9:16','1:1','4:5','16:9'].map(a=><option key={a}>{a}</option>)}</select></Field><Field label="Частота кадров"><select value={plan.fps} onChange={e=>patch('fps',+e.target.value)}><option value={30}>30 fps</option><option value={60}>60 fps</option></select></Field></div></>:tab==='crop'?<><h2>Композиция кадра</h2><div className="crop-options">{[['blur','Blurred Background','Полный исходник на размытой подложке'],['smart','Smart Face Crop','Плавно следит за крупнейшим видимым лицом'],['center','Center Crop','Центральная область'],['split','Split Layout','Левая и правая половины в двух рядах'],['manual','Manual Crop','Ручная позиция кадра']].map(([id,label,desc])=><button key={id} className={plan.crop_mode===id?'chosen':''} onClick={()=>patch('crop_mode',id)}><span className="radio-dot"/><div><strong>{label}</strong><small>{desc}</small></div>{plan.crop_mode===id&&<Check size={16}/>}</button>)}</div>{plan.crop_mode==='manual'&&<><Field label={`По горизонтали · ${Math.round(plan.crop_x*100)}%`}><input type="range" min={0} max={1} step={.01} value={plan.crop_x} onChange={e=>patch('crop_x',+e.target.value)}/></Field><Field label={`По вертикали · ${Math.round(plan.crop_y*100)}%`}><input type="range" min={0} max={1} step={.01} value={plan.crop_y} onChange={e=>patch('crop_y',+e.target.value)}/></Field></>}<div className="notice-box">Smart Crop использует детектор лиц OpenCV. При отсутствии надёжного трека включается размытие фона. Переключение активных говорящих и важные объекты автоматически не определяются.</div></>:tab==='subtitles'?<><h2>Субтитры по словам</h2><Toggle label="Встроить субтитры в видео" checked={plan.subtitles.enabled} onChange={v=>sub('enabled',v)}/><Field label="Пресет"><select value={plan.subtitles.preset} onChange={e=>{setPlan({...plan,subtitles:{...plan.subtitles,...presets[e.target.value],preset:e.target.value}});setDirty(true);setPreview(false)}}>{Object.keys(presets).map(p=><option key={p}>{p}</option>)}</select></Field><div className="form-grid"><Field label="Шрифт"><select value={plan.subtitles.font} onChange={e=>sub('font',e.target.value)}>{['Arial','Helvetica','Georgia'].map(f=><option key={f}>{f}</option>)}</select></Field><Field label="Размер (1080px)"><input type="number" min={24} max={140} value={plan.subtitles.size} onChange={e=>sub('size',+e.target.value)}/></Field><Field label="Основной цвет"><input type="color" value={plan.subtitles.color} onChange={e=>sub('color',e.target.value)}/></Field><Field label="Активное слово"><input type="color" value={plan.subtitles.active_color} onChange={e=>sub('active_color',e.target.value)}/></Field><Field label="Слов в строке"><input type="number" min={1} max={8} value={plan.subtitles.words_per_line} onChange={e=>sub('words_per_line',+e.target.value)}/></Field><Field label="Отступы (1080px)"><input type="number" min={24} max={250} value={plan.subtitles.margin} onChange={e=>sub('margin',+e.target.value)}/></Field><Field label="Контур"><input type="number" min={0} max={10} value={plan.subtitles.outline} onChange={e=>sub('outline',+e.target.value)}/></Field><Field label="Тень"><input type="number" min={0} max={10} value={plan.subtitles.shadow} onChange={e=>sub('shadow',+e.target.value)}/></Field></div><Field label="Позиция по высоте"><input type="range" min={.12} max={.88} step={.01} value={plan.subtitles.position} onChange={e=>sub('position',+e.target.value)}/></Field><Field label="Анимация"><select value={plan.subtitles.animation} onChange={e=>sub('animation',e.target.value)}><option value="none">Без анимации</option><option value="highlight">Подсветка слов</option><option value="pop">Pop + подсветка</option></select></Field><Toggle label="Жирный шрифт" checked={plan.subtitles.bold} onChange={v=>sub('bold',v)}/><p className="muted small-text">Смена стиля не запускает AI повторно. MP4, ASS и SRT создаются при рендере.</p><details className="caption-word-editor"><summary>Исправить текст субтитров</summary><p className="muted small-text">Текст меняется только в этом клипе. Исходные word timestamps сохраняются.</p><div className="word-edit-list">{(plan.caption_words||words).filter((w:any)=>plan.segments.some((s:any)=>w.start>=s.start&&w.end<=s.end)).map((w:any,i:number)=><label key={i}><time>{time(w.start)}</time><input aria-label={`Слово ${i+1}`} maxLength={120} value={w.word} onChange={e=>{const base=plan.caption_words||words.filter((word:any)=>plan.segments.some((seg:any)=>word.start>=seg.start&&word.end<=seg.end)).map((word:any)=>({word:word.word,start:word.start,end:word.end}));patch('caption_words',base.map((word:any)=>word.start===w.start&&word.end===w.end?{...word,word:e.target.value}:word))}}/></label>)}</div>{plan.caption_words&&<Button size="sm" onClick={()=>patch('caption_words',null)}>Восстановить распознанный текст</Button>}</details></>:tab==='audio'?<><AudioReplacementControls value={plan.audio_replacement} onChange={v=>patch('audio_replacement',v)}/><h2>Естественный звук</h2><Toggle label="Нормализация громкости" description="FFmpeg loudnorm · −16 LUFS, пик −1,5 dB" checked={plan.normalize_audio} onChange={v=>patch('normalize_audio',v)}/><Toggle label="Мягкое шумоподавление" checked={plan.denoise} onChange={v=>patch('denoise',v)}/><Field label={`Громкость · ${Math.round(plan.volume*100)}%`}><input type="range" min={0} max={2} step={.05} value={plan.volume} onChange={e=>patch('volume',+e.target.value)}/></Field><Field label="Кодировщик"><select value={plan.encoder} onChange={e=>patch('encoder',e.target.value)}><option value="auto">Auto · VideoToolbox / libx264</option><option value="videotoolbox">Apple VideoToolbox</option><option value="software">Software · libx264</option></select></Field></>:<><h2>Текст и метаданные</h2><Field label="Название клипа"><input value={title} maxLength={180} onChange={e=>{setTitle(e.target.value);setDirty(true)}}/></Field><Field label="Варианты заголовков"><div className="metadata-lines">{clip.data.titles?.length?clip.data.titles.map((t:string,i:number)=><button key={i} onClick={()=>{setTitle(t);setDirty(true)}}>{t}<Copy size={13}/></button>):<p>Нет дополнительных заголовков</p>}</div></Field><Field label="Описание"><div className="readable-text">{clip.data.description||clip.data.summary||'Описание не создано'}</div></Field><p className="muted">{clip.data.hashtags?.join(' ')}</p><p className="muted small-text">В локальном режиме заголовок извлекается из речи. Дополнительные AI-варианты создаёт Gemini.</p></>}</div></div></div></>
}

function QueuePage({jobs,act,pending}:any){const [filter,setFilter]=useState('all'),[logsId,setLogsId]=useState('');const shown=jobs.filter((j:Job)=>filter==='all'||(filter==='active'?['Running','Queued','Paused'].includes(j.status):j.status===filter));const active=jobs.filter((j:Job)=>['Running','Queued','Paused'].includes(j.status));const progress=active.length?active.reduce((n:number,j:Job)=>n+j.progress,0)/active.length:0;const control=(j:Job,a:string)=>act(()=>post(`/jobs/${j.id}/${a}`));return <><PageTitle title="Очередь обработки" subtitle={`${active.length} незавершённых задач · этапы восстанавливаются из SQLite`} action={<div className="button-row"><Button disabled={pending||!jobs.some((j:Job)=>['Running','Queued'].includes(j.status))} onClick={()=>act(()=>Promise.all(jobs.filter((j:Job)=>['Running','Queued'].includes(j.status)).map((j:Job)=>post(`/jobs/${j.id}/pause`))))}><Pause size={14}/>Пауза</Button><Button disabled={pending||!jobs.some((j:Job)=>j.status==='Paused')} onClick={()=>act(()=>Promise.all(jobs.filter((j:Job)=>j.status==='Paused').map((j:Job)=>post(`/jobs/${j.id}/resume`))))}><Play size={14}/>Продолжить</Button><Button disabled={pending||!jobs.some((j:Job)=>j.status==='Failed')} onClick={()=>act(()=>Promise.all(jobs.filter((j:Job)=>j.status==='Failed').map((j:Job)=>post(`/jobs/${j.id}/retry`))))}><RotateCcw size={14}/>Повтор ошибок</Button></div>}/>{active.length>0&&<div className="overall-progress panel"><div className="spread"><span>Прогресс незавершённых задач</span><strong>{Math.round(progress)}%</strong></div><div className="progress"><i style={{width:progress+'%'}}/></div></div>}<div className="toolbar"><div className="tabs">{[['all','Все задачи'],['active','В работе'],['Completed','Завершённые'],['Failed','Ошибки']].map(([id,label])=><button key={id} className={filter===id?'selected':''} onClick={()=>setFilter(id)}>{label}</button>)}</div><span className="muted small-text">Whisper 1 · AI 1 · FFmpeg 1</span></div>{shown.length?<div className="job-list">{shown.map((j:Job)=><article className="job-row" key={j.id}><div className="job-main"><div className="job-type">{j.kind==='render'?<Clapperboard size={20}/>:['download','export'].includes(j.kind)?<Download size={20}/>:<ScanLine size={20}/>}</div><div><strong>{j.clip_title||j.source_name}</strong><small>{j.kind==='render'?'Создание Reel':j.kind==='download'?'Скачивание YouTube':j.kind==='export'?'ZIP с готовыми роликами':'Анализ исходника'} · {j.id.slice(0,8)}</small>{j.output&&<small className="job-file" title={j.output.path}>Файл: {j.output.filename}</small>}{j.error&&<p className="job-error">{j.error}</p>}</div></div><div className="job-progress"><div className="spread"><span>{status(j.stage)}</span><small>{Math.round(j.progress)}%</small></div><div className="progress"><i style={{width:j.progress+'%'}}/></div>{j.kind==='download'&&j.checkpoints?.download_progress?.downloaded_bytes>0&&<small className="muted">{bytes(j.checkpoints.download_progress.downloaded_bytes)}{j.checkpoints.download_progress.total_bytes?' / '+bytes(j.checkpoints.download_progress.total_bytes):''}{j.checkpoints.download_progress.speed?' · '+bytes(j.checkpoints.download_progress.speed)+'/с':''}</small>}</div><Badge value={j.status}/><div className="job-actions">{j.output&&<Button size="sm" disabled={pending} title={j.output.path} onClick={()=>act(()=>post(`/jobs/${j.id}/reveal`),REVEALED)}><FolderOpen size={14}/>{REVEAL_LABEL}</Button>}{j.output&&j.kind==='render'&&<a className="button secondary small" href={j.output.download_url} download><Download size={13}/>Скачать MP4</a>}{j.kind==='export'&&j.status==='Completed'&&j.checkpoints?.download_url&&<a className="button secondary small" href={j.checkpoints.download_url} download><Download size={13}/>Скачать ZIP</a>}{j.kind==='download'&&j.status==='Failed'&&<Button size="sm" onClick={()=>{sessionStorage.setItem('factory-settings-section','youtube');location.hash='settings'}}>Аккаунт YouTube</Button>}{j.kind==='download'&&j.status==='Completed'&&j.source_id&&<Button size="sm" onClick={()=>{location.hash='sources'}}>Исходник<ArrowUpRight size={13}/></Button>}{['Queued','Running'].includes(j.status)&&<Button size="icon" title="Пауза" aria-label="Пауза" disabled={pending} onClick={()=>control(j,'pause')}><Pause size={14}/></Button>}{j.status==='Paused'&&<Button size="icon" title="Продолжить" aria-label="Продолжить" disabled={pending} onClick={()=>control(j,'resume')}><Play size={14}/></Button>}{['Failed','Cancelled'].includes(j.status)&&<Button size="icon" title="Повторить" aria-label="Повторить" disabled={pending} onClick={()=>control(j,'retry')}><RotateCcw size={14}/></Button>}{['Queued','Running','Paused'].includes(j.status)&&<Button size="icon" title="Отменить" aria-label="Отменить" disabled={pending} onClick={()=>control(j,'cancel')}><X size={15}/></Button>}<Button size="sm" variant="ghost" onClick={()=>setLogsId(logsId===j.id?'':j.id)}>Лог<ChevronDown size={13}/></Button></div>{logsId===j.id&&<pre className="job-log">{j.logs.map(l=>`${new Date(l.time*1000).toLocaleTimeString()}  ${l.message}`).join('\n')||'Задача ещё не запускалась'}</pre>}</article>)}</div>:<Empty title="Задач в этой очереди нет" icon={Layers}><p>Анализ и рендер запускаются из исходников и редактора.</p></Empty>}</>}

function SettingsPage({config,doctor,dash,act,toast}:any){const [section,setSection]=useState(()=>{const selected=sessionStorage.getItem('factory-settings-section');sessionStorage.removeItem('factory-settings-section');const requested=new URLSearchParams(location.search).get('settings');return requested&&['ai','voice','pilot','export','youtube','publish','storage','system'].includes(requested)?requested:selected||'ai'}),[values,setValues]=useState<any>(config.values),[keys,setKeys]=useState<Record<string,string>>({}),[dirty,setDirty]=useState(false);const change=(k:string,v:any)=>{setValues({...values,[k]:v});setDirty(true)};useEffect(()=>{if(!dirty)setValues(config.values)},[config.values,dirty]);const save=async()=>{const r=await act(()=>api('/settings',{method:'PUT',body:JSON.stringify({values,...keys})}),'Настройки сохранены');if(r){setKeys({});setDirty(false)}return r};return <><PageTitle title="Настройки" subtitle="Провайдеры, экспорт, расходы и локальное хранилище." action={<Button variant="default" disabled={!dirty&&!Object.keys(keys).length} onClick={save}>Сохранить изменения</Button>}/><div className="tabs settings-tabs">{[['ai','AI и модели'],['voice','Озвучка'],['pilot','AI-проба'],['export','Экспорт'],['youtube','Скачивание YouTube'],['publish','Публикации'],['storage','Хранилище'],['system','Диагностика']].map(([id,label])=><button key={id} className={section===id?'selected':''} onClick={()=>setSection(id)}>{label}</button>)}</div>{section==='ai'?<AISettings config={config} values={values} change={change} keys={keys} setKey={(k,v)=>setKeys(previous=>{const next={...previous};if(v)next[k]=v;else delete next[k];return next})} save={async()=>dirty||Object.keys(keys).length?save():config}/>:section==='voice'?<VoiceSettings config={config} values={values} change={change} keys={keys} setKey={(k,v)=>setKeys(previous=>{const next={...previous};if(v)next[k]=v;else delete next[k];return next})} save={async()=>dirty||Object.keys(keys).length?save():config}/>:section==='pilot'?<AuthorPilotSettings config={config} save={async()=>dirty||Object.keys(keys).length?save():config}/>:section==='export'?<div className="settings-row"><div><h2>Новые клипы</h2><p>Эти значения применяются к новым монтажным планам. В Clip Studio у каждого клипа свои настройки.</p></div><div className="panel settings-form"><div className="form-grid"><Field label="Формат"><select value={values.aspect} onChange={e=>change('aspect',e.target.value)}>{['9:16','1:1','4:5','16:9'].map(a=><option key={a}>{a}</option>)}</select></Field><Field label="Частота кадров"><select value={values.fps} onChange={e=>change('fps',+e.target.value)}><option value={30}>30 fps</option><option value={60}>60 fps</option></select></Field></div><Field label="Субтитры"><select value={values.subtitle_preset} onChange={e=>change('subtitle_preset',e.target.value)}>{Object.keys(config.presets).map(p=><option key={p}>{p}</option>)}</select></Field><Field label="Кадрирование"><select value={values.crop_mode} onChange={e=>change('crop_mode',e.target.value)}>{[['blur','Blurred Background'],['smart','Smart Face Crop'],['center','Center Crop'],['split','Split Layout'],['manual','Manual']].map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></Field><Field label="Кодировщик"><select value={values.encoder} onChange={e=>change('encoder',e.target.value)}><option value="auto">Auto · VideoToolbox → libx264</option><option value="software">libx264</option><option value="videotoolbox">VideoToolbox</option></select></Field></div></div>:section==='publish'?<PublishingSettings values={values} change={change}/>:section==='youtube'?<div className="settings-row"><div><h2>Вход и скачивание</h2><p>Подключите аккаунт, чтобы скачивать доступные ему ролики, включая видео с подтверждением возраста. Сессия используется yt-dlp локально и не отправляется AI-провайдеру.</p></div><YouTubeAccount/></div>:section==='storage'?<><div className="settings-row"><div><h2>Локальные файлы</h2><p>Свободно {bytes(dash.disk.free)} из {bytes(dash.disk.total)}. Оригиналы не удаляются автоматически.</p></div><div className="panel settings-form">{doctor?.paths&&Object.entries(doctor.paths).map(([k,v]:any)=><Field key={k} label={k}><code className="path-code">{v}</code></Field>)}<Field label="Минимальный запас диска, МБ"><input type="number" min={128} value={values.min_free_mb} onChange={e=>change('min_free_mb',+e.target.value)}/></Field><Field label="Лимит одного файла, МБ"><input type="number" min={1} max={100000} value={values.max_upload_mb} onChange={e=>change('max_upload_mb',+e.target.value)}/></Field></div></div><div className="settings-row"><div><h2>Временный кэш</h2><p>Очистка аудио, превью и временных кадров. Транскрипции, AI-ответы, проекты и готовые ролики сохраняются.</p></div><div className="panel settings-form"><Button onClick={async()=>{if(confirm('Удалить временные файлы? Оригиналы, AI-кэш, проекты и рендеры сохранятся.')){const r=await act(()=>post('/storage/clear-cache'));if(r)toast(`Освобождено ${bytes(r.removed_bytes)}`)}}}><Trash2 size={15}/>Очистить временный кэш</Button></div></div></>:<div className="settings-row"><div><h2>Локальная обработка</h2><p>Один процесс Whisper, один облачный анализ и один FFmpeg одновременно. Число ограничено для памяти и температуры.</p><p>Реальный Gemini без подключённого ключа не проверен.</p></div><div className="panel settings-form">{doctor?Object.entries(doctor).filter(([k,v])=>typeof v==='string'||typeof v==='number'||typeof v==='boolean').map(([k,v])=><div className="diagnostic-row" key={k}><span>{k}</span><code>{String(v)}</code></div>):<p>Диагностика недоступна</p>}<h3>Границы автоматизации</h3>{doctor?.limits?.map((l:string,i:number)=><p className="muted" key={i}>{l}</p>)}</div></div>}</>}

